import{_ as n}from"./CeKGlpnk.js";import{_ as r}from"./Q3fdnSrt.js";import{_ as c,c as l,a as e,b as s,w as d,f as p,o as m,d as u,p as f,e as v}from"./D596Mi9W.js";import"./BDaexoIX.js";const _=""+new URL("undraw4.DcxzOOXy.png",import.meta.url).href,g={},o=a=>(f("data-v-49229ef5"),a=a(),v(),a),y=p('<div class="grid mx-3 fadein animation-duration-400 animation-iteration-1 mb-5" data-v-49229ef5><div class="col-12 sm:col-12 md:col-8 lg:col-8 xl:col-8" data-v-49229ef5><p style="color:#055c9f;font-size:18px;height:0px;" data-v-49229ef5>QUIENES SOMOS?</p><p class="consultoriaSoftware" data-v-49229ef5><i class="pi pi-chart-line consultoriaSoftware" style="color:#055c9f;" data-v-49229ef5></i> Transformación Digital en la Industria: Innovación y Competitividad </p><p style="font-size:20px;color:gray;" data-v-49229ef5> En IMIMEX, nos especializamos en el desarrollo de software industrial y administrativo, brindando soluciones a la medida, consultoría de software y servicios de nearshoring. Nuestro compromiso es impulsar la eficiencia y productividad de las empresas a través de nuestra experiencia y forma de trabajo; Nos adaptamos a sus necesidades específicas. </p></div><div class="col-12 sm:col-12 md:col-4 lg:col-4 xl:col-4 flex align-items-center justify-content-center" data-v-49229ef5><img alt="user header" src="'+_+'" class="undraw2" data-v-49229ef5></div><div class="col-12 sm:col-12 md:col-6 lg:col-6 xl:col-6" data-v-49229ef5><p class="consultoriaSoftware" data-v-49229ef5><i class="pi pi-megaphone consultoriaSoftware" style="color:#055c9f;" data-v-49229ef5></i> Nuestra Misión </p><p style="font-size:20px;color:gray;" data-v-49229ef5> En IMIMEX queremos transformar y optimizar los procesos empresariales mediante el desarrollo de soluciones de software innovadoras, personalizadas y de alta calidad. Nos comprometemos a proporcionar tecnología de vanguardia que potencie la eficiencia, productividad y competitividad de nuestros clientes, asegurando su éxito en un entorno empresarial en constante evolución. </p></div><div class="col-12 sm:col-12 md:col-6 lg:col-6 xl:col-6" data-v-49229ef5><p class="consultoriaSoftware" data-v-49229ef5><i class="pi pi-sparkles consultoriaSoftware" style="color:#055c9f;" data-v-49229ef5></i> Nuestra Visión </p><p style="font-size:20px;color:gray;" data-v-49229ef5> En IMIMEX trabajamos a diario para ser líderes en México en el desarrollo de software innovador y personalizado, reconocidos por nuestra capacidad para transformar y optimizar los procesos empresariales. Aspiramos a crear un futuro donde las empresas de todo el mundo puedan alcanzar su máximo potencial gracias a nuestras soluciones tecnológicas avanzadas y nuestro compromiso inquebrantable con la excelencia y la innovación. </p></div></div>',1),x={class:"company-integration"},h=o(()=>e("h2",null,"Software, instrumentación y automatización",-1)),w=o(()=>e("p",null,"Aplicamos nuestra experiencia en software industrial y control de procesos a los sistemas de los edificios. Integramos climatización, iluminación, seguridad y energía para que la información del inmueble se convierta en decisiones de operación.",-1)),z=o(()=>e("p",null,"Como integradores certificados EcoXpert de Schneider Electric en Building Automation y Power Automation, acompañamos el diagnóstico, la ingeniería, el suministro e instalación, la puesta en marcha y el mantenimiento.",-1));function I(a,S){const i=n,t=r;return m(),l("div",null,[y,e("section",x,[h,w,z,s(i),s(t,{to:"/edificios-inteligentes"},{default:d(()=>[u("Conozca nuestra línea de Edificios Inteligentes →")]),_:1})])])}const B=c(g,[["render",I],["__scopeId","data-v-49229ef5"]]);export{B as default};
